const raw = $input.first().json || {};
const body = raw.body ?? raw;
const a = body.survey_answers ?? body;
const m = body.metadata ?? {};
const submitted = m.submittedAt
  ? new Date(m.submittedAt).toLocaleString('es-MX', { timeZone: 'America/Monterrey' })
  : '—';
const esc = (s) => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

return [{ json: {
  type: body.type || 'contact_inquiry',
  tracking_id: a.tracking_id || m.tracking_id || '—',
  nombre: esc(a.contact_name || a.name || a.nombre || '—'),
  telefono: esc(a.contact_phone || a.phone || a.telefono || m.phoneNumber || '—'),
  correo: esc(a.contact_email || a.email || a.correo || '—'),
  sucursal: a.contact_branch || 'general',
  motivo: esc(a.contact_reason || a.razon || '—'),
  mensaje: esc(a.contact_message || a.mensaje || '—'),
  source: m.source || 'contact',
  submitted_at_local: submitted,
  submitted_at_utc: m.submittedAt || '—',
  raw: body
}}];

parameters.text:
=Analiza el siguiente mensaje de contacto recibido en ANCHOR:23 Beauty Club, Saltillo MX, y genera un análisis interno en español.

DATOS:
- Nombre: {{ $json.nombre }}
- Sucursal: {{ $json.sucursal }}
- Motivo: {{ $json.motivo }}
- Mensaje: "{{ $json.mensaje }}"

Responde SOLO con un objeto JSON exacto (sin markdown, sin texto extra):
{
  "categoria": "queja|consulta|reservacion|felicitacion|informacion|otro",
  "urgencia": "alta|media|baja",
  "tono": "positivo|neutral|negativo|urgente",
  "resumen": "1-2 oraciones del contexto y necesidad del contacto",
  "accion_recomendada": "acción concreta y específica para el equipo",
  "tiempo_respuesta": "inmediato|24h|48h|sin_urgencia"
}

parameters.jsCode:
const survey = $('contact_parse').item.json;
const raw    = $input.first().json.text || $input.first().json.output || '{}';
let analysis;
try {
  analysis = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch(e) {
  analysis = { categoria: 'otro', urgencia: 'media', tono: 'neutral', resumen: raw.slice(0, 200), accion_recomendada: 'Revisar manualmente', tiempo_respuesta: '24h' };
}
const urgEmoji  = { alta:'🔴', media:'🟡', baja:'🟢' };
const tonoEmoji = { positivo:'😊', neutral:'😐', negativo:'😟', urgente:'⚠️' };
const urgencia_emoji = urgEmoji[analysis.urgencia]  || '⚪';
const tono_emoji     = tonoEmoji[analysis.tono]     || '⚪';
return [{ json: { ...survey, analysis, urgencia_emoji, tono_emoji } }];

const d = $input.first().json;
function sanitize(html) {
  if (!html) return null;
  return html
    .replace(/<link[^>]*>/gi, '')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<img[^>]*>/gi, '')
    .replace(/@import[^;]+;/gi, '')
    .replace(/url\(['"]?https?:\/\/[^)'"\s]+['"]?\)/gi, 'none');
}
const slug = (s) => String(s || 'doc')
  .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
  .replace(/[^a-zA-Z0-9]+/g,'_').replace(/^_|_$/,'').toLowerCase();
const cleanColor = sanitize(d.html_internal);
const cleanBW    = sanitize(d.html_internal_bw);
if (!cleanColor) throw new Error('html_internal vacío');
const base = `${slug(d.tracking_id)}_${slug(d.nombre)}`;
const binary = {
  html_color: await this.helpers.prepareBinaryData(Buffer.from(cleanColor,'utf-8'),'index.html','text/html'),
  html_bw:    await this.helpers.prepareBinaryData(Buffer.from(cleanBW||cleanColor,'utf-8'),'index.html','text/html'),
};
return [{ json: { ...d, _base: base }, binary }];

const all = $input.all();
const colorItem = all.find(i => i.binary?.pdf_color) || all[0];
const bwItem    = all.find(i => i.binary?.pdf_bw)    || all[1];
const bin = {};
if (colorItem?.binary?.pdf_color) bin.pdf_color = colorItem.binary.pdf_color;
if (bwItem?.binary?.pdf_bw)       bin.pdf_bw    = bwItem.binary.pdf_bw;
if (!bin.pdf_color) throw new Error('pdf_color no llegó de Gotenberg');
return [{ json: { ...(colorItem?.json || {}) }, binary: bin }];

const item  = $input.first();
const base  = item.json._base || 'anchor_doc';
const bin   = item.binary || {};
if (bin.pdf_color) bin.pdf_color = { ...bin.pdf_color, fileName: `${base}_color.pdf`, mimeType: 'application/pdf' };
if (bin.pdf_bw)    bin.pdf_bw    = { ...bin.pdf_bw,    fileName: `${base}_bw.pdf`,    mimeType: 'application/pdf' };
return [{ json: { ...item.json }, binary: bin }];

