={{ (() => {
const d = $('html_contact').item.json;
const a = d.analysis || {};
const div = '─────────────────────';
const pretty = (s) => String(s||'—').replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
const urgEmoji  = { alta:'🔴', media:'🟡', baja:'🟢' };
const urg_e = urgEmoji[a.urgencia] || '⚪';
return [
  `✉️ *Nuevo Contacto · ANCHOR:23*`,
  div,
  `👤 *Nombre:* ${d.nombre}`,
  `📞 ${d.telefono || '—'}`,
  `📧 ${d.correo || '—'}`,
  d.motivo && d.motivo !== '—' ? `📌 *Motivo:* ${pretty(d.motivo)}` : '',
  div,
  `💬 _\"${d.mensaje}\"_`,
  div,
  `${urg_e} *Urgencia:* ${a.urgencia || '—'}  ·  📂 ${a.categoria || '—'}`,
  a.resumen ? `\n📝 ${a.resumen}` : '',
  a.accion_recomendada ? `\n🎯 *Acción:* ${a.accion_recomendada}` : '',
  div,
  `🕐 ${d.submitted_at_local}`,
  `🔖 \`${d.tracking_id}\``
].filter(x => x !== '').join('\n');
})() }}
